        acts = Gtk.Box(spacing=8)
        if is_loaded:
            kind, admin = self.loaded_project_admin()
            # (con los logotipos de siempre: el globo, VS Code, phpMyAdmin y WordPress o PrestaShop)
            # (los que se ven, su orden y su estilo, como se haya elegido: nv_place_buttons)
            web = self.project_web()
            btns = {"web": nv_button(logo("globo", 18), "Abrir web", "Abrir %s" % web,
                                     lambda *_: self.open_uri(web), "nv-proyecto-btn")}
            code = vscode_app()
            if code is not None:
                img = None
                if code.get_icon() is not None:
                    img = Gtk.Image.new_from_gicon(code.get_icon(), Gtk.IconSize.BUTTON)
                    img.set_pixel_size(18)
                btns["vscode"] = nv_button(img or "text-editor-symbolic", "VS Code",
                                           "Abrir en Visual Studio Code", lambda *_: self.open_in_vscode(),
                                           "nv-proyecto-btn")
            # (el repositorio del proyecto en el navegador, solo si tiene: su remote origin)
            repo = repo_button(os.path.join(HTDOCS, x["name"]), self.open_uri)
            if repo is not None:
                btns["repo"] = repo
            pma = nv_button(logo("phpmyadmin", 18), "phpMyAdmin", None, lambda *_: self.open_project_pma(), "nv-proyecto-btn")
            pma.set_sensitive(bool(self.loaded_project_db()))
            btns["pma"] = pma
            adm = nv_button(logo("prestashop" if kind == "ps" else "wordpress", 18), "Panel",
                            "Abrir el panel de administración",
                            lambda *_: self.open_project_admin(), "nv-proyecto-btn")
            adm.set_sensitive(bool(admin))
            adm.nv_logo = "prestashop" if kind == "ps" else "wordpress"
            btns["panel"] = adm
            btns["docker"] = nv_button(logo("docker", 18), "Docker", "Montar en Docker",
                                       lambda *_: self.nv_docker_loaded(x), "nv-proyecto-btn")
            btns["compartir"] = self.nv_share_button(web.rstrip("/"), os.path.join(HTDOCS, x["name"]), x["name"])
            # El registro general de Apache: lo primero que se mira con un error (el del vhost, en Herramientas)
            has_log = os.path.isfile(APACHE_ERROR_LOG)
            logb = nv_button(logo("log", 18), "Log", "Ver el log de Apache" if has_log else "Aún no hay log de Apache",
                             lambda *_: self.show_log_tail(APACHE_ERROR_LOG), "nv-proyecto-btn")
            logb.set_sensitive(has_log)
            btns["log"] = logb
            btns["actualizar"] = nv_button(logo("actualizar", 18), "Actualizar", "Actualizar proyecto",
                                           lambda *_: self.nv_update_project(x), "nv-proyecto-btn")
            busy_guard(btns["actualizar"], self.busy).set_sensitive(True)
            if x["kind"] in ("wp", "ps"):
                btns["imagenes"] = self.nv_images_button(x)
            eject = nv_button("media-eject-symbolic", None, "Desmontar el proyecto",
                              lambda *_: self.on_unload_project(), flat=True)
            # (en varias líneas si no caben: con los botones grandes, la fila pedía más que la ventana)
            flow = nv_button_flow()
            self.nv_place_buttons(flow, btns, [(eject, ("icono", "media-eject-symbolic"), "Desmontar")])
            nv_flow_add(flow, eject)
            acts.pack_start(flow, True, True, 0)
        else:
            acts.pack_start(nv_button("media-playback-start-symbolic", "Cargar", None,
                                      lambda *_: self.on_load_folder(x), "nv-azul"), False, False, 0)
        # (⋮, pegado a la derecha; con un proyecto cargado, del tamaño de los demás botones)
        more = self.nv_more_menu(x)
        if is_loaded:
            self.nv_restyle(more, buttons_conf(), ("icono", "view-more-symbolic"), "Más")
        acts.pack_end(more, False, False, 0)
        # Si su carpeta tiene un dominio en los vhosts: falsearlo o dejar de falsearlo desde aquí, como
        # en Dominios y hosts
        if is_loaded:
            for h in reversed(self.project_hosts(x["name"])):
                fake = h["fake"]
                host = Gtk.Box(spacing=10, margin_end=10)
                texts = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, valign=Gtk.Align.CENTER)
                texts.pack_start(label("Host falseado" if fake else "Falsear Host", halign=Gtk.Align.END), False, False, 0)
                texts.pack_start(label(h["name"], "nv-chico", "nv-tenue", halign=Gtk.Align.END, ellipsize=2,
                                       max_width_chars=28, tooltip_text=h["name"]), False, False, 0)
                host.pack_start(texts, False, False, 0)
                sw = Gtk.Switch(active=fake, valign=Gtk.Align.CENTER, tooltip_text=host_switch_tip(h))
                sw.connect("state-set", self.on_host_switch, h)
                host.pack_start(sw, False, False, 0)
                acts.pack_end(host, False, False, 0)
        card.pack_start(acts, False, False, 0)
        self.hero_box.pack_start(card, False, False, 0)
        self.hero_box.show_all()


class NvActualizarProyecto:
    """Actualizar un proyecto, sus menús, crearlo, importarlo y borrarlo."""

    # --- Actualizar proyecto: la BBDD y el código de producción, arrastrados o elegidos ---

    def nv_drop_zone(self, title, formats, symbol_name, choosers, on_path):
        """Zona donde arrastrar un fichero o una carpeta, con sus botones de elegir. choosers: (texto,
        es carpeta). on_path(ruta) devuelve el motivo si no vale. Devuelve (widget, poner la ruta)."""
        ev = css(Gtk.EventBox(), "nv-zona")
        # (alta: es donde se suelta, tiene que verse bien)
        ev.set_size_request(-1, 112)
        box = Gtk.Box(spacing=16, margin_start=20, margin_end=18, margin_top=16, margin_bottom=16)
        ev.add(box)
        box.pack_start(css(icon(symbol_name, 36), "nv-zona-icono"), False, False, 0)
        # (en una rejilla: airy_dialog centra los textos de las cajas verticales; aquí, junto al icono, a la izquierda)
        texts = Gtk.Grid(orientation=Gtk.Orientation.VERTICAL, row_spacing=2, valign=Gtk.Align.CENTER)
        texts.add(label(title, "grupo-titulo", halign=Gtk.Align.START))
        name = label("Arrástralo aquí: %s" % formats, "dim-label", ellipsize=2, halign=Gtk.Align.START)
        texts.add(name)
        box.pack_start(texts, True, True, 0)

        def put(path):
            why = on_path(path)
            ctx = name.get_style_context()
            ctx.remove_class("error")
            if why:
                ctx.add_class("error")
                name.set_label(why)
            else:
                name.set_label(path or "Arrástralo aquí: %s" % formats)
            name.set_tooltip_text(path or None)
            clear_btn.set_visible(bool(path) and not why)
            # (el recuadro azul, solo con algo incorporado o al arrastrar encima)
            zone_ctx = ev.get_style_context()
            if path and not why:
                zone_ctx.add_class("nv-zona-lista")
            else:
                zone_ctx.remove_class("nv-zona-lista")

        def choose(folder):
            dlg = Gtk.FileChooserDialog(title=title, transient_for=ev.get_toplevel(), modal=True,
                                        action=Gtk.FileChooserAction.SELECT_FOLDER if folder else Gtk.FileChooserAction.OPEN)
            dlg.add_button("Cancelar", Gtk.ResponseType.CANCEL)
            dlg.add_button("Elegir", Gtk.ResponseType.ACCEPT)
            dlg.set_current_folder(GLib.get_user_special_dir(GLib.UserDirectory.DIRECTORY_DOWNLOAD) or os.path.expanduser("~"))
            resp = run_dialog(dlg)
            path = dlg.get_filename()
            dlg.destroy()
            if resp == Gtk.ResponseType.ACCEPT and path:
                put(path)

        def dropped(_w, _ctx, _x, _y, data, _info, _time):
            uris = data.get_uris()
            if uris:
                try:
                    put(GLib.filename_from_uri(uris[0])[0])
                except GLib.Error:
                    put("")
        ev.drag_dest_set(Gtk.DestDefaults.ALL, [], Gdk.DragAction.COPY)
        ev.drag_dest_add_uri_targets()
        ev.connect("drag-data-received", dropped)
        clear_btn = nv_button("window-close-symbolic", None, "Quitar", lambda *_: put(""), flat=True)
        # (oculto hasta que haya algo elegido, sin dejar oculto su icono)
        clear_btn.get_child().show_all()
        clear_btn.set_no_show_all(True)
        box.pack_start(clear_btn, False, False, 0)
        for text, folder in choosers:
            box.pack_start(nv_button(None, text, None, lambda *_, f=folder: choose(f)), False, False, 0)
        return ev, put

    def nv_update_project(self, x):
        """Actualizar el proyecto cargado con lo de producción: su BBDD y su código."""
        folder = x["name"]
        dlg = Gtk.Dialog(title="Actualizar proyecto", transient_for=self.win, modal=True, use_header_bar=True)
        dlg.set_default_size(680, -1)
        dlg.get_header_bar().set_subtitle(folder)
        box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=14, margin=22)
        state = {"sql": "", "code": ""}

        def set_sql(path):
            why = ""
            if path and not (os.path.isfile(path) and path.lower().endswith((".sql", ".gz", ".zip"))):
                why, path = "Tiene que ser .sql, .sql.gz o .zip", ""
            state["sql"] = path
            update()
            return why

        def set_code(path):
            why = ""
            ok = os.path.isdir(path) or (os.path.isfile(path) and path.lower().endswith(
                (".zip", ".tar", ".tgz", ".tar.gz", ".tar.bz2", ".tar.xz")))
            if path and not ok:
                why, path = "Tiene que ser un .zip, un .tar.gz o una carpeta", ""
            state["code"] = path
            update()
            return why

        zone, _put = self.nv_drop_zone("Base de datos de producción", ".sql, .sql.gz o .zip", "drive-multidisk-symbolic",
                                       [("Elegir fichero…", False)], set_sql)
        box.pack_start(zone, False, False, 0)
        line = Gtk.Box(spacing=8)
        db_text = label("", "dim-label")
        line.pack_start(db_text, False, False, 0)
        # (su nombre, como texto; solo si el proyecto no tiene ninguna hay que escribirlo)
        known_db = self.loaded_project_db() or ""
        db_entry = Gtk.Entry(text=known_db, width_chars=28, max_length=64)
        line.pack_start(label(known_db, "nv-bbdd", selectable=True) if known_db else db_entry, False, False, 0)
        db_copy = label("(al confirmar, puedes guardar antes una copia de la actual)", "dim-label")
        line.pack_start(db_copy, False, False, 0)
        box.pack_start(line, False, False, 0)
        zone, _put = self.nv_drop_zone("Código de producción", ".zip, .tar.gz o carpeta", "folder-symbolic",
                                       [("Elegir fichero…", False), ("Elegir carpeta…", True)], set_code)
        box.pack_start(zone, False, False, 0)
        # Qué hacer con la carpeta: siempre a la vista, para saber lo que va a pasar
        merge = Gtk.RadioButton.new_with_label(None, "Fusionar: copia lo que trae y deja lo demás de la carpeta")
        over = Gtk.RadioButton.new_with_label_from_widget(merge, "Sobrescribir: además borra lo que no traiga")
        modes = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=4)
        modes.pack_start(merge, False, False, 0)
        modes.pack_start(over, False, False, 0)
        modes.pack_start(label("Se escribe sobre %s/%s. Su .git no se toca; lo sustituido o borrado solo se puede "
                               "recuperar si al confirmar guardas antes una copia en ~/nexum-backups." % (HTDOCS, folder),
                               "aviso-rojo", wrap=True), False, False, 0)
        box.pack_start(modes, False, False, 0)
        dlg.get_content_area().add(box)
        dlg.add_button("Cancelar", Gtk.ResponseType.CANCEL)
        go = css(dlg.add_button("Actualizar…", Gtk.ResponseType.ACCEPT), "nv-azul")

        def update(*_):
            db_ok = bool(re.fullmatch(r"[A-Za-z0-9_-]{1,64}", db_entry.get_text().strip()))
            go.set_sensitive(bool(state["sql"] or state["code"]) and (not state["sql"] or db_ok))
            modes.set_sensitive(bool(state["code"]))
            # (sin fichero de BBDD no se toca: se sigue usando la misma)
            db_text.set_label("Se carga en la BBDD" if state["sql"] else "Se sigue usando la BBDD")
            db_copy.set_visible(bool(state["sql"]))
            line.set_visible(bool(known_db or state["sql"]))
            if not known_db:
                db_entry.set_sensitive(bool(state["sql"]))
        db_entry.connect("changed", update)
        dlg.show_all()
        update()
        resp = run_dialog(dlg)
        db = db_entry.get_text().strip()
        mode = "sobrescribir" if over.get_active() else "fusionar"
        dlg.destroy()
        if resp == Gtk.ResponseType.ACCEPT:
            self.nv_update_project_ask(folder, state["sql"], db, state["code"], mode)

    def nv_update_project_ask(self, folder, sql, db, code, mode):
        """Antes de copiar: si es un repositorio, ¿git pull antes?, avisando de lo que no se ha subido."""
        def start(pull, backup):
            args = ["actualizar-proyecto", folder] + (["--copia"] if backup else [])
            if code:
                args += ["--codigo", code, "--modo", mode] + (["--pull"] if pull else [])
            if sql:
                args += ["--bd", sql]
            # (también solo con el código: al volver a cargarlo, su configuración vuelve a esta BBDD)
            if db:
                args += ["--base", db]

            def run(_pwd=None):
                self.run_task("Actualizando %s" % folder, args, progress=True, env=self.db_env(),
                              done_text="%s actualizado" % folder,
                              cancel_text=("¿Cancelar la actualización?",
                                           "El proyecto se queda a medias, con lo hecho hasta ahora."
                                           + (" Lo sustituido sigue en ~/nexum-backups." if backup else ""),
                                           "Cancelar la actualización"))
            if sql:
                self.check_db_access(run)
            else:
                run()

        what = []
        if code:
            what.append(("Se fusiona «%s» con %s/%s." if mode == "fusionar" else
                         "Se sobrescribe la carpeta con «%s» en %s/%s: se borra lo que no traiga.")
                        % (os.path.basename(code), HTDOCS, folder))
        if sql:
            what.append("La BBDD %s se vacía y se carga «%s»." % (db, os.path.basename(sql)))

        def got(_rc, out):
            f = next((x for x in parse_lines(out) if x[0] == "G" and len(x) >= 6), None)
            is_git = bool(code) and f is not None and f[1] == "1"
            extra = copy_check()
            if not is_git:
                if confirm(self.win, "¿Actualizar %s?" % folder, "", "Actualizar", steps=what, extra=extra):
                    start(False, extra.wanted)
                return False
            dirty, ahead = int(f[3] or 0), int(f[4] or 0)
            state = ["Rama %s" % (f[2] or "sin rama (HEAD suelto)")]
            if dirty:
                state.append("%s sin commit" % plural(dirty, "cambio", "cambios"))
            if ahead:
                state.append("%s sin subir" % plural(ahead, "commit", "commits"))
            text = ["  ·  ".join(state)]
            if dirty or ahead:
                text.append("Revisa antes lo que estás trabajando: lo sustituido no queda en git (solo en la copia, "
                            "si la guardas).")
            has_pull = f[5] == "1" and bool(f[2])
            text.append("Con el pull, la carpeta se equipara antes al repositorio. Si choca con tus cambios, se para "
                        "sin tocar nada." if has_pull else "No se puede hacer pull: no tiene origin o no está en una rama.")
            dlg = Gtk.MessageDialog(transient_for=self.win, modal=True, message_type=Gtk.MessageType.QUESTION,
                                    buttons=Gtk.ButtonsType.NONE, text="¿Hacer git pull antes de copiar?")
            dlg.get_message_area().pack_start(steps_box(what, "\n\n".join(text)), False, False, 0)
            dlg.get_message_area().pack_start(extra, False, False, 0)
            dlg.add_button("Cancelar", Gtk.ResponseType.CANCEL)
            dlg.add_button("Copiar sin pull", Gtk.ResponseType.NO)
            if has_pull:
                css(dlg.add_button("Hacer pull y copiar", Gtk.ResponseType.YES), "nv-azul")
            dlg.show_all()
            resp = run_dialog(dlg)
            dlg.destroy()
            if resp in (Gtk.ResponseType.YES, Gtk.ResponseType.NO):
                start(resp == Gtk.ResponseType.YES, extra.wanted)
            return False
        run_quick(["gui-proyecto-git", folder], got)

    def nv_menu_button(self, text, icon_name, items, tip=None):
        m = css(Gtk.MenuButton(tooltip_text=tip), "nv-proyecto-btn")
        b = Gtk.Box(spacing=6)
        b.pack_start(icon_name if isinstance(icon_name, Gtk.Widget) else icon(icon_name), False, False, 0)
        if text:
            b.pack_start(Gtk.Label(label=text), False, False, 0)
        m.add(b)
        pop = Gtk.Popover(relative_to=m)
        box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, margin=4)
        for t, fn in items:
            mb = Gtk.ModelButton(text=t)
            mb.connect("clicked", lambda *_, fn=fn: fn())
            box.pack_start(mb, False, False, 0)
        box.show_all()
        pop.add(box)
        m.set_popover(pop)
        return m

    def nv_add_env_menu(self, x):
        return self.nv_menu_button(None, "list-add-symbolic", [
            ("En otra versión de PHP (copiar su BBDD)…", lambda: self.on_replicate(x)),
            ("En Docker…", lambda: self.nv_docker_new_for(x))],
            "Añadir entorno: llevar el proyecto a otra versión de PHP o a Docker")

    def nv_docker_new_for(self, x):
        """«En Docker…» del + de Entorno: el diálogo «Proyecto en Docker» con ese proyecto elegido. Con Docker
        apagado o sin instalar, o si el proyecto ya está en Docker (su carpeta no sale en ese diálogo), lo
        mismo que «Añadir entorno en Docker…» del menú ⋮ (instalarlo, arrancarlo u otra versión de PHP)."""
        def got(rc, out):
            self.on_docker_data(rc, out)
            d = self.docker or {}
            if not d.get("ready") or not d.get("php") or self.nv_docker_of(x["name"]):
                self.nv_docker_add_env(x)
                return False
            self.docker_form.update(folder=x["name"], source=None, domain_set=False,
                                    domain=docker_slug(x["name"]) + ".docker.local")
            self.nv_docker_new()
            return False
        run_quick(["gui-docker"], got)

    def nv_row_menu(self, x):
        """Menú ⋮ de una fila de la lista (aparece al pasar el ratón, con Cargar): llevar el proyecto a
        otra versión o a Docker, importar su SQL y lo del menú Más, sin cambiar el proyecto de arriba."""
        items = [("Añadir entorno en otra versión de PHP…", lambda: self.on_replicate(x)),
                 ("Añadir entorno en Docker…", lambda: self.nv_docker_add_env(x)),
                 ("Importar SQL…", lambda: self.nv_import(x))] + self.nv_more_items(x)
        return self.nv_menu_button(None, "view-more-symbolic", items)

    def nv_more_menu(self, x):
        items = self.nv_more_items(x)
        loaded = self.loaded_project_folder()
        if loaded is not None and os.path.basename(loaded) == x["name"]:
            # (solo el cargado: se exporta con la versión de PHP donde está y su BBDD de esa versión)
            items.insert(2, ("Exportar proyecto…", lambda: self.nv_export_project(x)))
        return self.nv_menu_button(None, "view-more-symbolic", items)

    def nv_more_items(self, x):
        items = [("Opciones de la BBDD…", lambda: self.on_link_project(x)),
                 ("Abrir la carpeta", lambda: self.open_uri("file://%s/%s" % (HTDOCS, x["name"])))]
        for dp in self.nv_docker_of(x["name"]):
            # (uno por entorno de Docker: cada uno dice el suyo)
            items.append(("Eliminar de Docker (PHP %s)…" % ", ".join(dp.get("versions") or [dp["php"]]),
                          lambda dp=dp: self.on_docker_delete(dp)))
        db = self.project_base(x)
        if x["kind"] == "ps" and db:
            items.append(("Vaciar la caché de la tienda", lambda: self.run_task(
                "Vaciando la caché de la tienda de %s" % db, ["vaciar-cache", x["name"]],
                done_text="Caché vaciada", auto_close=True)))
        items.append(("Limpiar proyecto…", lambda: self.nv_clean_project(x)))
        if x["kind"] in ("ps", "wp"):
            items.append(("Imágenes de producción…", lambda: self.nv_wp_media(x)))
        if x["kind"] == "ps":
            items.append(("Descargar de producción las imágenes que faltan…", lambda: self.nv_ps_images(x)))
        if self.project_hosts(x["name"]):
            items.append(("Vaciar la caché de Chrome…", lambda: self.nv_browser_cache()))
        items.append(("Personalizar los botones…", lambda: self.nv_buttons_dialog()))
        items.append(("Borrar el proyecto…", lambda: self.nv_delete_project(x)))
        return items

    def nv_browser_cache(self):
        """Más, «Vaciar la caché de Chrome…» (de un proyecto con dominio): tras falsear o dejar de falsear su
        dominio, Chrome puede seguir un rato en la otra web, con su caché de DNS y las conexiones que ya tenía
        abiertas. Chrome no deja que otro programa abra sus páginas internas ni pulse sus botones: se copia
        la dirección y se dice qué pulsar."""
        Gtk.Clipboard.get(Gdk.SELECTION_CLIPBOARD).set_text(BROWSER_SOCKETS_URL, -1)
        message(self.win, "Vaciar la caché de Chrome",
                "Si después de falsear o dejar de falsear un dominio Chrome sigue en la otra web (la real o la "
                "de este equipo), es por las conexiones que tenía abiertas y su caché de DNS. Nexum ya corta "
                "esas conexiones al cambiar hosts; si aun así sigue, en Chrome:\n\n"
                "1. Pega en la barra de direcciones %s (ya está copiada) y pulsa Intro.\n"
                "2. Pulsa «Flush socket pools».\n"
                "3. A la izquierda, en «DNS», pulsa «Clear host cache».\n"
                "4. Recarga la pestaña del proyecto con Ctrl+Mayús+R.\n\n"
                "Chrome no deja que otro programa abra esa página ni pulse sus botones. En Firefox: "
                "about:networking#dns y «Clear DNS Cache»." % BROWSER_SOCKETS_URL)

    # --- Exportar proyecto: un zip con su código y su BBDD (gui-exportar-proyecto y exportar-proyecto) ---

    def nv_export_project(self, x):
        """⋮, Exportar proyecto… (del cargado): primero se mira su código en git. Con cambios sin commit no se
        deja exportar (se dice cuáles); si no, el diálogo con lo que se exporta."""
        name = x["name"]

        def got(_rc, out):
            lines = parse_lines(out)
            f = {ln[0]: ln for ln in lines}
            g, v = f.get("G"), f.get("V")
            if not g or len(g) < 6 or not v or len(v) < 5:
                message(self.win, "No se puede exportar «%s»" % name,
                        out.strip()[-400:] or "Sin respuesta del instalador.", Gtk.MessageType.ERROR)
                return False
            if not v[1]:
                message(self.win, "No hay ninguna versión activa",
                        "Para exportar un proyecto hace falta la versión de PHP donde está cargado.",
                        Gtk.MessageType.ERROR)
                return False
            if g[1] == "2":
                message(self.win, "No se puede comprobar el código de «%s»" % name,
                        "git no ha podido leer la carpeta: %s\n\nArréglalo antes de exportar." % g[2],
                        Gtk.MessageType.ERROR)
                return False
            n = int(g[3]) if g[3].isdigit() else 0
            if g[1] == "1" and n:
                shown = [ln[1] for ln in lines if ln[0] == "C" and len(ln) >= 2]
                more = "\n  y %d más" % (n - len(shown)) if n > len(shown) else ""
                message(self.win, "«%s» tiene cambios sin commit" % name,
                        "Tiene %s sin commit en git:\n\n%s%s\n\nHaz commit antes de exportar (o descarta esos "
                        "cambios): el zip tiene que llevar lo mismo que el repositorio."
                        % (plural(n, "cambio", "cambios"), "\n".join("  " + c for c in shown), more),
                        Gtk.MessageType.WARNING)
                return False
            self.nv_export_dialog(x, f)
            return False
        run_quick(["gui-exportar-proyecto", name], got)

    def nv_export_dialog(self, x, f):
        """«Exportar «carpeta»»: de qué versión de PHP, las casillas del código y de su BBDD (marcadas) y los
        pasos, que cambian con ellas. Al aceptar, la tarea exportar-proyecto."""
        name = x["name"]
        g, v = f["G"], f["V"]
        active = self.data.get("active") if self.data else None
        # (la BBDD del proyecto cargado, como la ve la ventana; si no está en esta versión, la del script)
        db = self.loaded_project_db()
        if not db or db not in self.data["dbs"].get(active, []):
            db = f.get("B", ["B", ""])[1]
        dest = f.get("D", ["D", ""])[1] or os.path.expanduser("~")
        zip_name = f.get("N", ["N", ""])[1] or "%s_php…_nexum.zip" % name
        size = int(f["S"][1]) if "S" in f and f["S"][1].isdigit() else 0
        ver_label = "%s · PHP %s" % (v[2], v[3] or "?")
        dlg = Gtk.MessageDialog(transient_for=self.win, modal=True, message_type=Gtk.MessageType.QUESTION,
                                buttons=Gtk.ButtonsType.NONE, text="Exportar «%s»" % name)
        ahead = int(g[4]) if g[4].isdigit() else 0
        if g[1] == "1":
            git = "El código está en git, sin cambios sin commit%s." % (" (rama %s)" % g[2] if g[2] else "")
        else:
            git = "No es un repositorio git: no se puede comprobar si tiene cambios sin commit."
        dlg.format_secondary_text("Se exporta de la versión activa, donde está cargado: %s.\n%s" % (ver_label, git))
        widen(dlg)
        extra = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=6)
        code = Gtk.CheckButton(label="Código: %s/%s · %s (sin la carpeta .git)" % (HTDOCS, name, fmt_size(size)),
                               active=True)
        extra.pack_start(code, False, False, 0)
        if db:
            base = Gtk.CheckButton(label="Base de datos: %s (%s)" % (db, v[2]), active=True)
        else:
            base = Gtk.CheckButton(label="Base de datos: Sin BBDD vinculada", active=False, sensitive=False)
        extra.pack_start(base, False, False, 0)
        if ahead:
            extra.pack_start(label("Tiene %s sin subir a su rama remota: el zip los lleva, pero el repositorio "
                                   "remoto no." % plural(ahead, "commit", "commits"),
                                   "aviso-rojo", wrap=True, max_width_chars=60, xalign=0), False, False, 0)
        holder = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, margin_top=8)
        extra.pack_start(holder, False, False, 0)
        dlg.get_message_area().pack_start(extra, False, False, 0)
        dlg.add_button("Cancelar", Gtk.ResponseType.CANCEL)
        ok = css(dlg.add_button("Exportar", Gtk.ResponseType.ACCEPT), "verde")
        dlg.set_default_response(Gtk.ResponseType.ACCEPT)

        def update(*_):
            with_code, with_db = code.get_active(), base.get_active() and bool(db)
            steps = []
            if with_code:
                steps.append("Se copia el código de %s/%s en %s/, sin .git (los enlaces que salen de la carpeta "
                             "no van)." % (HTDOCS, name, name))
            if with_db:
                steps.append("Se descarga la BBDD %s de %s en %s.sql, como «Descargar»: sin el administrador de "
                             "pruebas ni los cambios del correo de pruebas." % (db, v[2], db))
            steps.append("Se escribe el zip con un LEEME-nexum.txt donde elijas (al pulsar «Exportar», la ventana "
                         "de guardar, en %s y con el nombre %s, que puedes cambiar). Si falla o lo cancelas, no "
                         "queda nada." % (dest, zip_name))
            for child in holder.get_children():
                holder.remove(child)
            holder.pack_start(steps_box(steps), False, False, 0)
            holder.show_all()
            ok.set_sensitive(with_code or with_db)
        code.connect("toggled", update)
        base.connect("toggled", update)
        dlg.show_all()
        update()
        resp = run_dialog(dlg)
        with_code, with_db = code.get_active(), base.get_active() and bool(db)
        dlg.destroy()
        if resp != Gtk.ResponseType.ACCEPT or not (with_code or with_db):
            return
        path, overwrite = self.nv_export_where(name, dest, zip_name)
        if not path:
            return
        args = ["exportar-proyecto", name, "--zip", path] + (["--sobrescribir"] if overwrite else []) + \
            ([] if with_code else ["--sin-codigo"]) + (["--bd", db] if with_db else ["--sin-bd"])
        folder = os.path.dirname(path)

        def done(success, task, _p):
            if success:
                task.offer("Mostrar en la carpeta", lambda: self.open_uri(GLib.filename_to_uri(folder)))

        def start(_pwd=None):
            self.run_task("Exportando %s" % name, args, progress=True, env=self.db_env() if with_db else None,
                          on_done=done, done_text="«%s» exportado en %s" % (name, path),
                          cancel_text=("¿Cancelar la exportación?", "No se guarda nada: el zip a medias se borra.",
                                       "Cancelar la exportación"))
        if with_db:
            self.check_db_access(start)
        else:
            start()

    def nv_export_where(self, name, dest, zip_name):
        """La ventana de guardar del sistema: dónde va el zip y con qué nombre (de partida, en descargas y con su
        nombre de siempre). Devuelve (ruta, si se escribe encima de uno que ya existe) o (None, False)."""
        dlg = Gtk.FileChooserDialog(title="Guardar el proyecto exportado «%s»" % name, transient_for=self.win,
                                    action=Gtk.FileChooserAction.SAVE, do_overwrite_confirmation=True)
        dlg.add_button("Cancelar", Gtk.ResponseType.CANCEL)
        css(dlg.add_button("Guardar", Gtk.ResponseType.ACCEPT), "verde")
        dlg.set_default_response(Gtk.ResponseType.ACCEPT)
        zips = Gtk.FileFilter()
        zips.set_name("Zip (*.zip)")
        zips.add_pattern("*.zip")
        zips.add_pattern("*.ZIP")
        dlg.add_filter(zips)
        dlg.set_current_folder(dest if os.path.isdir(dest) else os.path.expanduser("~"))
        if zip_name and "…" not in zip_name:
            dlg.set_current_name(zip_name)
        else:
            dlg.set_current_name("%s_nexum.zip" % name)
        path = dlg.get_filename() if run_dialog(dlg) == Gtk.ResponseType.ACCEPT else None
        dlg.destroy()
        if not path:
            return None, False
        # (sin .zip, se le pone; si así ya existe, la ventana de guardar no lo ha preguntado: se pregunta aquí)
        if not path.lower().endswith(".zip"):
            path += ".zip"
            if os.path.lexists(path) and not confirm(
                    self.win, "¿Reemplazar «%s»?" % os.path.basename(path),
                    "Ya existe en %s. Si lo reemplazas, se pierde lo que tenía." % os.path.dirname(path),
                    "Reemplazar", destructive=True):
                return None, False
        return path, os.path.lexists(path)

    def nv_images_button(self, x):
        """Imágenes de producción: las que falten se traen de su web real al pedirlas la página (WordPress y tiendas)."""
        b = nv_button(logo("imagenes", 18), "Imágenes de producción",
                      "Traer de producción las imágenes que falten",
                      lambda *_: self.nv_wp_media(x), "nv-proyecto-btn")
        busy_guard(b, self.busy).set_sensitive(True)
        return b

    def nv_wp_media(self, x):
        """media-proyecto: las imágenes que le falten a un WordPress (wp-content/uploads) o a una tienda (img) se
        traen de su web real al pedirlas la página, por el intermediario de imágenes, y se quedan en su carpeta.
        Se propone el dominio de su base (home o siteurl; en una tienda, su shop_url). En una tienda, además,
        «Descargar todas…» (ps-imagenes)."""
        name = x["name"]
        shop = x["kind"] == "ps"

        def got(rc, out):
            f = {l[0]: l[1] for l in parse_lines(out) if len(l) >= 2}
            saved, guess = f.get("G", ""), f.get("D", "")
            dlg = Gtk.Dialog(title="Imágenes de producción", transient_for=self.win, modal=True, use_header_bar=True)
            dlg.set_default_size(520, -1)
            box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=12, margin=22)
            box.pack_start(label("Imágenes de producción de %s" % name, "nv-titulo", wrap=True), False, False, 0)
            text = ("No se descarga nada por adelantado. Cuando la tienda pide una imagen que no está en su carpeta img, "
                    "Nexum la trae en ese momento de su web real, te la enseña y la deja guardada en img: solo se trae "
                    "lo que ves, y la siguiente vez ya sale de tu equipo. Funciona aunque su dominio esté falseado en "
                    "este equipo (pregunta su dirección al DNS cifrado y comprueba su certificado real). Con LAMPP; en "
                    "el Apache de Docker, no." if shop else
                    "No se descarga nada por adelantado. Cuando la web pide una imagen de wp-content/uploads que no "
                    "está en tu carpeta, Nexum la trae en ese momento de su web real, te la enseña y la deja guardada: "
                    "solo se trae lo que ves, y la siguiente vez ya sale de tu equipo. Funciona aunque su dominio esté "
                    "falseado en este equipo. Los vídeos y los PDF no se guardan: se piden a la web real con una "
                    "redirección (mientras esté cargado y en el Apache de Docker, donde las imágenes también van así).")
            box.pack_start(label(text, "nv-tenue", wrap=True, max_width_chars=60), False, False, 0)
            entry = Gtk.Entry(text=saved or guess, placeholder_text="ejemplo.com", max_length=80,
                              activates_default=True)
            box.pack_start(entry, False, False, 0)
            if guess and not saved:
                box.pack_start(label("Es el dominio de su BBDD: compruébalo antes de guardar.", "nv-chico", "nv-tenue"),
                               False, False, 0)
            dlg.get_content_area().add(box)
            if saved:
                css(dlg.add_button("Quitar", Gtk.ResponseType.REJECT), "destructive-action")
            if shop:
                dlg.add_button("Descargar todas…", Gtk.ResponseType.APPLY)
            dlg.add_button("Cancelar", Gtk.ResponseType.CANCEL)
            ok = css(dlg.add_button("Guardar", Gtk.ResponseType.OK), "nv-azul")
            dlg.set_default_response(Gtk.ResponseType.OK)

            def clean():
                return re.sub(r"^https?://", "", entry.get_text().strip().lower()).rstrip("/")

            # (el mismo de antes también: se vuelve a aplicar, en web.local y en el Apache de Docker)
            def update(*_):
                d = clean()
                ok.set_sensitive(bool(DOMAIN_RX.match(d)) and not d.endswith((".local", ".test")))
            entry.connect("changed", update)
            dlg.show_all()
            update()
            resp = run_dialog(dlg)
            prod = clean()
            dlg.destroy()
            if resp == Gtk.ResponseType.APPLY:
                self.nv_ps_images(x)
            elif resp == Gtk.ResponseType.REJECT:
                self.run_task("Quitando las imágenes de producción de %s" % name, ["media-proyecto", name, "quitar"],
                              done_text="%s ya no pide nada a producción" % name, auto_close=True)
            elif resp == Gtk.ResponseType.OK:
                self.run_task("Imágenes de producción de %s" % name, ["media-proyecto", name, prod],
                              done_text="%s trae de %s las imágenes que le faltan" % (name, prod), auto_close=True)
            return False
        run_quick(["gui-wp-produccion", name], got, env=self.db_env())

    def nv_ps_images(self, x):
        """ps-imagenes: una tienda se ve con su dominio real falseado (una redirección volvería aquí), así
        que las imágenes que faltan se descargan de la web real, con la lista de su BBDD."""
        name = x["name"]
        if not confirm(self.win, "¿Descargar las imágenes que le faltan a %s?" % name,
                       "Se descargan de su web real las imágenes de productos, categorías y marcas que no "
                       "están en su carpeta img (la lista sale de su BBDD: la de la versión activa o, si no está "
                       "allí, la de su proyecto del Apache de Docker). Van a su carpeta img, la misma con LAMPP y con "
                       "Docker. Lo que ya "
                       "está en local no se toca. Con muchos productos puede tardar y ocupar bastante.\n\n"
                       "Su dominio está falseado en este equipo: se busca con DNS cifrado (Cloudflare) y se "
                       "comprueba su certificado real.", "Descargar"):
            return
        self.check_db_access(lambda _pwd: self.run_task(
            "Descargando las imágenes de %s" % name, ["ps-imagenes", name], env=self.db_env(),
            done_text="Imágenes de %s descargadas" % name))

    # Limpiar proyecto (gui-limpiar-proyecto y limpiar-proyecto): cada clave, con su título y lo que se hace
    PROJECT_CLEAN_ITEMS = [("cache", "Caché", "se vacía su caché"),
                           ("registros", "Registros", "se borran sus registros"),
                           ("actualizaciones", "Restos de actualizaciones", "se vacían los restos de las actualizaciones")]

    def nv_clean_project(self, x):
        """⋮, Limpiar proyecto…: lo que tiene de caché, registros y restos de actualizaciones (gui-limpiar-proyecto),
        cada cosa con sus carpetas, lo que ocupa y su casilla (marcada); se confirma con lo que se va a hacer y se
        lanza limpiar-proyecto con lo marcado. Si no tiene nada, se dice."""
        name = x["name"]

        def got(_rc, out):
            found = [(f[1], int(f[2]), int(f[3]), f[4]) for f in parse_lines(out)
                     if f[0] == "P" and len(f) >= 5 and f[2].isdigit() and f[3].isdigit() and int(f[3]) > 0]
            if not found:
                message(self.win, "Nada que limpiar", "No hay cachés ni registros que limpiar en %s." % name)
                return False
            self.nv_clean_project_dialog(name, found)
            return False
        run_quick(["gui-limpiar-proyecto", name], got)

    def nv_clean_project_dialog(self, name, found):
        info = {k: (t, step) for k, t, step in self.PROJECT_CLEAN_ITEMS}
        dlg = Gtk.MessageDialog(transient_for=self.win, modal=True, message_type=Gtk.MessageType.QUESTION,
                                buttons=Gtk.ButtonsType.NONE, text="Limpiar «%s»" % name)
        dlg.format_secondary_text("Marca lo que quieres limpiar. Las carpetas se quedan, vacías; nada de las "
                                  "imágenes ni de lo que se sube a la web.")
        widen(dlg)
        extra = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=4)
        checks = []
        for key, b, n, paths in found:
            title = info.get(key, (key, ""))[0]
            chk = Gtk.CheckButton(label="%s · %s · %s" % (title, fmt_size(b), plural(n, "fichero", "ficheros")),
                                  active=True, margin_top=6)
            extra.pack_start(chk, False, False, 0)
            extra.pack_start(css(label(", ".join(p for p in paths.split(",") if p), wrap=True, xalign=0,
                                       max_width_chars=60, margin_start=26), "dim-label", "subtitulo"), False, False, 0)
            checks.append((key, b, n, paths, chk))
        extra.pack_start(label("Lo que se limpia no se puede recuperar: no se hacen copias.", "aviso-rojo", wrap=True,
                               max_width_chars=60, xalign=0, margin_top=10), False, False, 0)
        dlg.get_message_area().pack_start(extra, False, False, 0)
        dlg.add_button("Cancelar", Gtk.ResponseType.CANCEL)
        ok = css(dlg.add_button("Limpiar lo marcado…", Gtk.ResponseType.ACCEPT), "destructive-action")
        dlg.set_default_response(Gtk.ResponseType.CANCEL)

        def update(*_):
            ok.set_sensitive(any(c[4].get_active() for c in checks))
        for c in checks:
            c[4].connect("toggled", update)
        dlg.show_all()
        update()
        resp = run_dialog(dlg)
        chosen = [c[:4] for c in checks if c[4].get_active()]
        dlg.destroy()
        if resp != Gtk.ResponseType.ACCEPT or not chosen:
            return
        steps = ["%s (%s · %s): %s (%s)." % (info.get(k, (k, ""))[0], fmt_size(b), plural(n, "fichero", "ficheros"),
                                             info.get(k, ("", "se limpia"))[1], paths.replace(",", ", "))
                 for k, b, n, paths in chosen]
        warn = label("Lo que se limpia no se puede recuperar: no se hacen copias.", "aviso-rojo", wrap=True,
                     max_width_chars=60, xalign=0)
        if not confirm(self.win, "¿Limpiar «%s»?" % name, "Si algo es del administrador (lo que creó Apache), se "
                       "pide su contraseña.", "Limpiar", destructive=True, extra=warn, steps=steps):
            return
        self.run_task("Limpiando %s" % name, ["limpiar-proyecto", name] + [k for k, *_r in chosen],
                      done_text="%s limpio" % name, auto_close=True)

    def nv_delete_project(self, x):
        """Borra el proyecto entero (borrar-proyecto): su carpeta, sus vhosts y dominios, lo de Docker y,
        si se marca, su BBDD de la versión activa (la de phpMyAdmin), con copia si se marca. Hay que
        escribir el nombre de la carpeta para confirmar: la carpeta no se puede recuperar."""
        name = x["name"]
        active = self.data["active"] if self.data else None
        db = next((d for i, d in self.project_pairs(x) if i["folder"] == active), None)
        docker = self.nv_docker_of(name)
        dlg = Gtk.MessageDialog(transient_for=self.win, modal=True, message_type=Gtk.MessageType.WARNING,
                                buttons=Gtk.ButtonsType.NONE, text="¿Borrar el proyecto «%s»?" % name)
        what = ["su carpeta %s/%s" % (HTDOCS, name), "sus vhosts y las líneas de sus dominios en /etc/hosts"]
        if docker:
            what.append("sus contenedores de Docker (%s)" % ", ".join(dp["domain"] for dp in docker))
        dlg.format_secondary_markup("Se borran %s. <b>La carpeta no se puede recuperar.</b>"
                                    % GLib.markup_escape_text(", ".join(what[:-1]) + " y " + what[-1]))
        dlg.add_button("Cancelar", Gtk.ResponseType.CANCEL)
        ok = css(dlg.add_button("Borrar el proyecto", Gtk.ResponseType.ACCEPT), "destructive-action")
        dlg.set_default_response(Gtk.ResponseType.CANCEL)
        extra = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=8)
        drop = copy = None
        if db:
            drop = Gtk.CheckButton(label="Borrar también su BBDD «%s» (lampp-%s, la de phpMyAdmin)" % (db, active))
            copy = Gtk.CheckButton(label="Guardar antes una copia en ~/nexum-backups (se puede volver a cargar)",
                                   active=False, margin_start=24)
            no_copy = label("Sin copia, la BBDD no se podrá recuperar.", "error", wrap=True, max_width_chars=50,
                            margin_start=24)
            no_copy.set_no_show_all(True)
            extra.pack_start(drop, False, False, 0)
            extra.pack_start(copy, False, False, 0)
            extra.pack_start(no_copy, False, False, 0)
        extra.pack_start(label("Escribe %s para confirmar:" % name, "error", wrap=True, max_width_chars=50),
                         False, False, 0)
        entry = Gtk.Entry(activates_default=False)
        extra.pack_start(entry, False, False, 0)
        dlg.get_message_area().pack_start(extra, False, False, 0)

        def update(*_):
            if copy is not None:
                copy.set_sensitive(drop.get_active())
                no_copy.set_visible(drop.get_active() and not copy.get_active())
            ok.set_sensitive(entry.get_text().strip() == name)
        entry.connect("changed", update)
        if drop is not None:
            drop.connect("toggled", update)
            copy.connect("toggled", update)
        dlg.show_all()
        update()
        resp = run_dialog(dlg)
        with_db = bool(drop and drop.get_active())
        with_copy = bool(copy and copy.get_active())
        dlg.destroy()
        if resp != Gtk.ResponseType.ACCEPT:
            return
        args = ["borrar-proyecto", name]
        if with_db:
            args += ["--bd", db] + (["--copia"] if with_copy else [])
        done = "Proyecto «%s» borrado" % name + (" con su BBDD" if with_db else "") \
            + (" (copia en ~/nexum-backups)" if with_db and with_copy else "")

        def go(*_):
            self.run_task("Borrando el proyecto %s" % name, args, env=self.db_env() if with_db else None,
                          done_text=done)
        if with_db:
            self.check_db_access(go)
        else:
            go()

    def nv_import(self, x):
        pairs = self.project_pairs(x)
        act = next((d for i, d in pairs if i["folder"] == self.data["active"]), None)
        self.imp.update(project=x["name"], db=act or self.imp.get("db"))
        self.build_databases()
        self.show_tab("bbdd")
        self.toast("Elige el fichero en «Subir o actualizar una BBDD»: proyecto %s" % x["name"])

    def nv_new_project(self):
        # El asistente de siempre (clonar de git, version y BBDD), en una ventana aparte
        if getattr(self, "proj_box", None) is None:
            return
        if self.np_dialog is None:
            self.np_dialog = Gtk.Window(title="Nuevo proyecto", transient_for=self.win, modal=False)
            self.np_dialog.set_default_size(700, -1)
            self.np_dialog.connect("delete-event", lambda w, *_: (self.toggle_new_project(False), w.hide(), True)[2])
            if self.new_proj_rev.get_parent():
                self.new_proj_rev.get_parent().remove(self.new_proj_rev)
            box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, margin=20)
            box.pack_start(self.new_proj_rev, True, True, 0)
            self.np_dialog.add(box)
        self.toggle_new_project(True)
        self.np_dialog.show_all()

    def toggle_new_project(self, show):
        super().toggle_new_project(show)
        if not show and self.np_dialog is not None:
            self.np_dialog.hide()


class NvConfiguracion:
    """Títulos de las páginas, Hosts y Configuración por apartados."""

    def nv_page_title(self, box, symbol_name, title, sub, trailing=None):
        """Título grande arriba de una página hecha con los constructores de siempre (como el de las
        demás pestañas). trailing: un botón, a su derecha."""
        head = Gtk.Box(orientation=Gtk.Orientation.VERTICAL)
        tl = Gtk.Box(spacing=10)
        tl.pack_start(symbol(symbol_name, 26), False, False, 0)
        title_lbl = label(title, "nv-titulo-grande")
        tl.pack_start(title_lbl, False, False, 0)
        head.pack_start(tl, False, False, 0)
        sub_lbl = label(sub, "nv-chico", "nv-tenue", xalign=0, wrap=True)
        head.pack_start(sub_lbl, False, False, 0)
        parts = (tl, title_lbl, sub_lbl)
        if trailing is not None:
            line = Gtk.Box(spacing=12)
            line.pack_start(head, True, True, 0)
            line.pack_end(trailing, False, False, 0)
            head = line
        box.pack_start(head, False, False, 0)
        box.reorder_child(head, 0)
        head.show_all()
        return parts

    def build_hosts(self):
        super().build_hosts()
        # (los desplegables y el dominio, del mismo ancho: caben en los 2/3 de la tarjeta)
        for w in self.nv_walk(self.hosts_box):
            if isinstance(w, Gtk.ComboBox):
                narrow(w, 30)
            elif isinstance(w, Gtk.Entry):
                w.set_width_chars(30)
        view = nv_button("text-x-generic-symbolic", "Ver fichero de hosts",
                         "Ver %s" % (self.data["hosts"] if self.data else "/etc/hosts"),
                         self.on_view_hosts)
        self.nv_page_title(self.hosts_box, "network-workgroup-symbolic", "Dominios y hosts",
                           "Los dominios de los vhosts y los que se llevan a este equipo en /etc/hosts", view)

    def on_hosts_data(self, rc, out):
        old = self.hosts
        res = super().on_hosts_data(rc, out)
        # (el interruptor del proyecto cargado sigue a /etc/hosts; solo su recuadro, no toda la lista)
        if self.hosts != old and getattr(self, "nv_list", None) and self.projects and self.data:
            loaded = self.loaded_project_entry()
            if loaded is not None:
                self.nv_hero(loaded, loaded)
        return res

    def build_tools(self):
        # (antes de vaciar la pestaña: al soltar su tarjeta, GTK destruiría también el visor del correo)
        web = getattr(self, "mail_web", None)
        if web is not None and web.get_parent() is not None:
            web.get_parent().remove(web)
        super().build_tools()
        # Barrera entre webs (nexum barrera-web): encendida si no existe el fichero
        box, lb = tile_group("Seguridad entre webs",
                             "Impide que otra web abierta en tu navegador use tus proyectos locales sin que lo sepas.")
        on = not os.path.exists(os.path.join(LOG_DIR, "sin-barrera-entre-webs"))
        row = ActionRow("Barrera entre webs", "Encendida: tus proyectos solo aceptan lo que llega desde ellos mismos"
                        if on else "Apagada: enciéndela cuando acabes de probar los pagos")
        sw = busy_guard(Gtk.Switch(active=on, valign=Gtk.Align.CENTER), self.busy)
        sw.connect("notify::active", self.on_cross_site)
        row.add_suffix(sw)
        lb.add(row)
        # Webs permitidas (nexum barrera-web permitir|quitar): las de confianza, como el ERP de la empresa
        allowed = cross_site_allowed()
        row = ActionRow("Webs permitidas",
                        "La barrera deja pasar lo que mandan a tus proyectos (*.dominio vale también para sus subdominios)"
                        if allowed else
                        "Ninguna. Añade las de confianza (el ERP de tu empresa) para que puedan mandarte a tus proyectos "
                        "con un formulario, abrirlos en un iframe o hacerles peticiones (fetch)")
        row.subtitle.set_ellipsize(0)
        row.subtitle.set_line_wrap(True)
        row.subtitle.set_xalign(0)
        b = busy_guard(Gtk.Button(label="Añadir…", valign=Gtk.Align.CENTER), self.busy)
        b.connect("clicked", lambda *_: self.on_cross_site_allow())
        row.add_suffix(b)
        lb.add(row)
        for dom in allowed:
            row = ActionRow(dom, "%s y todos sus subdominios" % dom[2:] if dom.startswith("*.") else "Solo este dominio")
            row.add_prefix(css(symbol("security-high-symbolic", 18), "nv-permitida"))
            b = busy_guard(Gtk.Button(label="Quitar", valign=Gtk.Align.CENTER), self.busy)
            b.connect("clicked", lambda _b, d=dom: self.on_cross_site_unallow(d))
            row.add_suffix(b)
            lb.add(row)
        # Qué es, explicado: el problema, lo que hace, cuándo apagarla y dónde vale
        box.pack_start(label("Qué es", "nv-apartado-titulo", xalign=0, margin_top=20), False, False, 0)
        why = css(Gtk.ListBox(selection_mode=Gtk.SelectionMode.NONE, margin_top=6), "caja")
        for ic, title, text in CROSS_SITE_HELP:
            r = ActionRow(title, text)
            r.add_prefix(symbol(ic, 18))
            r.subtitle.set_ellipsize(0)
            r.subtitle.set_line_wrap(True)
            r.subtitle.set_xalign(0)
            why.add(r)
        box.pack_start(why, False, False, 0)
        self.tools_box.pack_start(box, False, False, 0)
        self.tools_box.reorder_child(box, 1)
        box.show_all()
        self.nv_components_tools()
        self.nv_tasks_tools()
        self.nv_docker_tools()
        self.nv_nginx_tools()
        self.nv_tunnel_tools()
        self.nv_mail_tools()
        self.nv_admin_tools()
        self.nv_github_tools()
        self.nv_look_tools()
        self.nv_clean_tools()
        self.nv_tools_sections()
        self.tools_title = self.nv_page_title(self.tools_box, "emblem-system-symbolic", "Configuración",
                                              "Elige un apartado en la columna de la izquierda")
        self.nv_tools_title()

    # Apartados de Configuración: su nombre en la columna de la izquierda, su icono y el orden (los que no
    # estén aquí, al final)
    TOOLS_SECTIONS = [("General", "General", "preferences-system-symbolic"),
                      ("Configuración", "Vhosts y hosts", "network-workgroup-symbolic"),
                      ("Seguridad entre webs", "Seguridad entre webs", "security-high-symbolic"),
                      ("Correo de pruebas (Mailpit)", "Correo de pruebas", "mail-unread-symbolic"),
                      ("Administrador de pruebas", "Administrador de pruebas", "avatar-default-symbolic"),
                      ("Docker", "Docker", "logo:docker"),
                      ("Nginx", "Nginx", "logo:nginx"),
                      ("Túnel de Cloudflare", "Túnel de Cloudflare", "network-transmit-receive-symbolic"),
                      ("GitHub (Repositorios)", "GitHub", "logo:github"),
                      ("Apariencia", "Apariencia", "preferences-desktop-appearance-symbolic"),
                      ("Limpieza", "Limpieza", "edit-clear-all-symbolic"),
                      ("Carpetas", "Carpetas", "folder-symbolic"),
                      ("XAMPP sin registrar", "XAMPP sin registrar", "drive-harddisk-symbolic"),
                      ("Información", "Información", "help-about-symbolic")]
    # Lo que va junto en General, cada uno en su bloque con su título, en este orden
    GENERAL_PARTS = ["Registro de errores", "Registro de tareas", "Parches nuevos", "Programa"]
    GENERAL_DESC = ("Los registros de errores de la web cargada y de Apache, el de las tareas que lanza la ventana, "
                    "los parches nuevos de lo que usa Nexum y el propio programa")

    def nv_tools_sections(self):
        """Configuración en dos columnas: a la izquierda, los encabezados de sus apartados; a la derecha, lo que
        se puede cambiar del elegido. Los apartados son los de siempre (cada constructor añade el suyo a
        tools_box): aqui se pasan a una hoja cada uno. Los de GENERAL_PARTS van juntos en la de General, cada
        uno con su título y su explicación. El elegido se recuerda al rehacer la pestaña."""
        groups = list(self.tools_box.get_children())
        for g in groups:
            self.tools_box.remove(g)
        order = {t: n for n, (t, _, _) in enumerate(self.TOOLS_SECTIONS)}
        info = {t: (name, ic) for t, name, ic in self.TOOLS_SECTIONS}

        def title_of(g):
            for w in self.nv_walk(g):
                if isinstance(w, Gtk.Label) and w.get_style_context().has_class("grupo-titulo"):
                    return w.get_label()
            return ""
        found = []
        parts = {}
        for n, g in enumerate(groups):
            t = title_of(g) or "Otros"
            if t in self.GENERAL_PARTS and t not in parts:
                parts[t] = g
            else:
                found.append((t, n, g))
        self.tools_parts = parts
        if parts:
            gen = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=30)
            for t in self.GENERAL_PARTS:
                g = parts.get(t)
                if g is None:
                    continue
                # (su explicación, a la vista debajo de su título, en lugar del símbolo de información)
                tlbl = next((w for w in self.nv_walk(g) if isinstance(w, Gtk.Label)
                             and w.get_style_context().has_class("grupo-titulo")), None)
                head = tlbl.get_parent() if tlbl is not None else None
                for c in head.get_children() if head is not None else []:
                    if isinstance(c, Gtk.EventBox) and c.get_tooltip_text():
                        desc = label(c.get_tooltip_text(), "dim-label", "subtitulo", xalign=0, wrap=True)
                        c.set_no_show_all(True)
                        c.hide()
                        g.pack_start(desc, False, False, 0)
                        g.reorder_child(desc, 1)
                        break
                gen.pack_start(g, False, False, 0)
            found.append(("General", -1, gen))
        found.sort(key=lambda x: (order.get(x[0], len(order)), x[1]))
        stack = Gtk.Stack(vhomogeneous=False, hhomogeneous=False, hexpand=True,
                          transition_type=Gtk.StackTransitionType.CROSSFADE, transition_duration=120)
        nav = css(Gtk.ListBox(valign=Gtk.Align.START), "nv-nav", "nv-subnav")
        rows = {}
        self.tools_desc = {"General": self.GENERAL_DESC}
        self.tools_extra = {}
        for title, _n, g in found:
            if title in rows:
                continue
            # (su nombre va en el título grande de arriba: aquí, sin repetirlo; su explicación, debajo de él.
            # General no: cada uno de sus bloques lleva el suyo)
            tlbl = None if title == "General" else next((w for w in self.nv_walk(g) if isinstance(w, Gtk.Label)
                                                         and w.get_style_context().has_class("grupo-titulo")), None)
            if tlbl is not None:
                head = tlbl.get_parent()
                kids = head.get_children()
                extra = []
                for n, c in enumerate(kids):
                    if c is not tlbl and isinstance(c, Gtk.EventBox) and c.get_tooltip_text():
                        self.tools_desc[title] = c.get_tooltip_text()
                    elif n > kids.index(tlbl):
                        # (lo de detrás del título, como el interruptor del correo, va al lado del título grande)
                        extra.append(c)
                    if c not in extra:
                        c.set_no_show_all(True)
                        c.hide()
                for c in extra:
                    head.remove(c)
                    c.set_valign(Gtk.Align.CENTER)
                    c.set_margin_start(14)
                    c.set_no_show_all(False)
                if extra:
                    self.tools_extra[title] = extra
                head.set_no_show_all(True)
                head.hide()
            stack.add_named(g, title)
            name, ic = info.get(title, (title, "emblem-system-symbolic"))
            row = Gtk.ListBoxRow()
            inner = Gtk.Box(spacing=10)
            inner.pack_start(MonoLogo(ic[5:], 16) if ic.startswith("logo:") else symbol(ic, 16), False, False, 0)
            inner.pack_start(label(name, ellipsize=3), True, True, 0)
            row.add(inner)
            row.section = title
            nav.add(row)
            rows[title] = row

        def picked(_lb, row):
            if row is not None:
                self.tools_section = row.section
                stack.set_visible_child_name(row.section)
                self.nv_tools_title()
        nav.connect("row-selected", picked)
        want = getattr(self, "tools_section", None)
        if want not in rows and found:
            want = found[0][0]
        for w in self.tools_side.get_children():
            w.destroy()
        self.tools_side.pack_start(label("CONFIGURACIÓN", "nv-seccion", margin_start=22, margin_top=16, margin_bottom=2),
                                   False, False, 0)
        self.tools_side.pack_start(nav, False, False, 0)
        self.tools_side.show_all()
        self.tools_box.pack_start(stack, True, True, 0)
        self.tools_nav = rows
        stack.show_all()
        if want:
            nav.select_row(rows[want])

    def nv_tools_title(self):
        """El título grande de Configuración: el del apartado abierto (su icono, su nombre y su explicación)."""
        parts = getattr(self, "tools_title", None)
        sec = getattr(self, "tools_section", None)
        if not parts or not sec:
            return
        tl, title_lbl, sub_lbl = parts
        info = {t: (name, ic) for t, name, ic in self.TOOLS_SECTIONS}
        name, ic = info.get(sec, (sec, "emblem-system-symbolic"))
        old = tl.get_children()[0]
        tl.remove(old)
        old.destroy()
        new = MonoLogo(ic[5:], 26) if ic.startswith("logo:") else symbol(ic, 26)
        tl.pack_start(new, False, False, 0)
        tl.reorder_child(new, 0)
        new.show()
        title_lbl.set_label(name)
        sub_lbl.set_label(getattr(self, "tools_desc", {}).get(sec) or "Configuración")
        # (lo que iba al lado del título del apartado: el de antes sale y entra el del abierto)
        for c in tl.get_children()[2:]:
            tl.remove(c)
        for c in getattr(self, "tools_extra", {}).get(sec, []):
            tl.pack_start(c, False, False, 0)
            c.show_all()

    # Administrador de pruebas (nexum admin-pruebas): la cuenta con la que el botón Panel entra en WordPress y
    # PrestaShop. La ventana lee el ajuste (test_admin_conf) y lo guarda con la orden, con la contraseña por la
    # entrada: así no sale en la línea de órdenes, ni en ps ni en el registro de tareas
    def nv_admin_who(self):
        """El administrador de pruebas de ahora, para los textos: su correo (y la contraseña, si es local)."""
        mail, _password, own = test_admin_conf()
        return "%s, con tu contraseña de Configuración" % mail if own else "local@local.test, contraseña local"

    def nv_admin_tools(self):
        """Configuración, Administrador de pruebas: su correo (que es también el usuario) y su contraseña, con un
        ojo para verla, «Guardar» y «Volver a local@local.test»."""
        mail, password, own = test_admin_conf()
        box, lb = tile_group("Administrador de pruebas",
                             "La cuenta con la que el botón «Panel» entra en el panel de WordPress y en el de "
                             "PrestaShop de tus proyectos. Nexum la crea, con rol de administrador, al cargar una "
                             "BBDD, y nunca va en las copias que descargas ni en las que exportas.")
        self.tools_box.pack_start(box, False, False, 0)
        now = ActionRow("Ahora", "%s (el tuyo)" % mail if own else
                        "local@local.test con la contraseña local (el de siempre: no has puesto otro)")
        now.add_prefix(symbol("avatar-default-symbolic", 18))
        lb.add(now)
        row = ActionRow("Correo (usuario)", "Mejor uno que no sea de verdad, como ana@local.test")
        entry_mail = Gtk.Entry(text=mail if own else "", width_chars=26, placeholder_text="ana@local.test",
                               input_purpose=Gtk.InputPurpose.EMAIL)
        row.add_suffix(entry_mail)
        lb.add(row)
        row = ActionRow("Contraseña", "De 4 a 64 letras sin tildes, números o %s" % TEST_ADMIN_PASS_CHARS)
        entry_pass = Gtk.Entry(text=password if own else "", width_chars=26, visibility=False,
                               input_purpose=Gtk.InputPurpose.PASSWORD, placeholder_text="Contraseña")
        entry_pass.set_icon_from_icon_name(Gtk.EntryIconPosition.SECONDARY, "view-reveal-symbolic")
        entry_pass.set_icon_tooltip_text(Gtk.EntryIconPosition.SECONDARY, "Mostrar la contraseña")

        def peek(e, _pos, _ev):
            on = not e.get_visibility()
            e.set_visibility(on)
            e.set_icon_from_icon_name(Gtk.EntryIconPosition.SECONDARY,
                                      "view-conceal-symbolic" if on else "view-reveal-symbolic")
            e.set_icon_tooltip_text(Gtk.EntryIconPosition.SECONDARY,
                                    "Ocultar la contraseña" if on else "Mostrar la contraseña")
        entry_pass.connect("icon-press", peek)
        row.add_suffix(entry_pass)
        lb.add(row)
        row = ActionRow("Guardar los cambios", "Sin espacios, comillas, \\, $ ni `. Las BBDD ya cargadas no cambian: se pone al "
                        "cargar una BBDD o al pulsar «Panel» en el proyecto")
        row.subtitle.set_ellipsize(0)
        row.subtitle.set_line_wrap(True)
        save = css(Gtk.Button(label="Guardar", sensitive=False), "verde")
        reset = Gtk.Button(label="Volver a local@local.test", sensitive=own,
                           tooltip_text="Vuelve a local@local.test con la contraseña local (los correos de antes "
                                        "tampoco van en las copias)")
        row.add_suffix(reset)
        row.add_suffix(save)
        lb.add(row)
        warn = label("", "nv-chico", "nv-correo-aviso", wrap=True, margin_top=6)
        warn.set_no_show_all(True)
        box.pack_start(warn, False, False, 0)
        notes = css(Gtk.ListBox(selection_mode=Gtk.SelectionMode.NONE, margin_top=14), "caja")
        for ic, title, text in (
                ("security-high-symbolic", "Una cuenta de verdad no se toca",
                 "Si una BBDD ya tiene un usuario de verdad con ese correo (sin la marca de Nexum), no se cambia ni "
                 "su contraseña ni su rol: ahí no se crea el de pruebas y se avisa. Elige otro correo."),
                ("document-save-symbolic", "Fuera de las copias",
                 "Al descargar una BBDD o exportar un proyecto se quita el de ahora, local@local.test y los que "
                 "hayas puesto antes, solo si llevan la marca de Nexum.")):
            r = ActionRow(title, text)
            r.add_prefix(symbol(ic, 18))
            r.subtitle.set_ellipsize(0)
            r.subtitle.set_line_wrap(True)
            r.subtitle.set_xalign(0)
            notes.add(r)
        box.pack_start(notes, False, False, 0)

        def problem():
            m, pw = entry_mail.get_text().strip(), entry_pass.get_text()
            if not m and not pw:
                return "Escribe el correo y la contraseña"
            if not test_admin_mail_ok(m):
                return "El correo no vale: solo letras sin tildes, números y . _ % + - con forma de correo " \
                       "(ana@local.test), hasta 60 caracteres"
            if m.lower() == "local@local.test":
                return "local@local.test es el de siempre: para volver a él, «Volver a local@local.test»"
            if not test_admin_pass_ok(pw):
                return "La contraseña no vale: de 4 a 64 letras sin tildes, números o " + TEST_ADMIN_PASS_CHARS
            return ""

        def changed(*_):
            m, pw = entry_mail.get_text().strip(), entry_pass.get_text()
            bad = problem() if (m or pw) else ""
            warn.set_label(bad)
            warn.set_visible(bool(bad) and bool(m and pw))
            busy_guard(save, self.busy).set_sensitive(not bad and (m, pw) != ((mail, password) if own else ("", "")))
        entry_mail.connect("changed", changed)
        entry_pass.connect("changed", changed)

        def done(rc, out):
            lines = [l for l in out.strip().splitlines() if l.strip() and not l.startswith("  [")]
            if rc != 0:
                warn.set_label(lines[-1] if lines else "No se ha podido guardar")
                warn.set_visible(True)
                return False
            self.toast(lines[0] if lines else "Guardado")
            self.build_tools()
            return False

        def on_save(*_):
            if problem():
                return
            if SIMULATE:
                self.toast("Simulación: no se guarda nada (el administrador de pruebas sigue igual)")
                return
            run_quick_input(["admin-pruebas", entry_mail.get_text().strip(), "-"], entry_pass.get_text() + "\n", done)

        def on_reset(*_):
            if SIMULATE:
                self.toast("Simulación: no se guarda nada (el administrador de pruebas sigue igual)")
                return
            run_quick(["admin-pruebas", "--quitar"], done)
        save.connect("clicked", on_save)
        reset.connect("clicked", on_reset)
        entry_mail.connect("activate", lambda *_: save.get_sensitive() and on_save())
        entry_pass.connect("activate", lambda *_: save.get_sensitive() and on_save())
        box.show_all()

    # Limpieza (nexum gui-limpieza y limpiar <clave>...): cada cosa, con su título, qué es, dónde está, para qué
    # servía y qué pasa si se limpia, lo que se hace (en la confirmación) y si va marcada de partida. Nada de
